window.EXAM_CHAPTER_DATA["west_econ"]["13_失业通胀与经济周期"] = {"id":"13_失业通胀与经济周期","name":"失业通胀与经济周期","kps":[{"id":"KP01","name":"奥肯定律","file":"教材笔记/06_西方经济学/13_失业通胀与经济周期/知识点/KP01_奥肯定律.md","questions":[{"id":"west_econ_13_失业通胀与经济周期_KP01_1","num":"1","stem":"奥肯定律描述的关系是：","options":{"A":"通胀率与失业率的反向关系","B":"失业率缺口与GDP缺口的反向关系","C":"利率与投资的反向关系","D":"汇率与净出口的反向关系"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP01_2","num":"2","stem":"奥肯定律的表达式为：","options":{"A":"$(Y-Y_f)/Y_f = -\\beta(u-u_n)$","B":"$\\pi = \\pi^e - \\beta(u-u_n)$","C":"$Y = Y_f + \\alpha(P-P^e)$","D":"$MV = PY$"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP01_3","num":"3","stem":"已知 $Y_f = 200$ 万亿元，$u_n = 4\\%$，$u = 6\\%$，$\\beta = 2$，则实际GDP为：","options":{"A":"184 万亿元","B":"192 万亿元","C":"196 万亿元","D":"208 万亿元"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP01_4","num":"4","stem":"奥肯定律中 $\\beta$ 的含义是：","options":{"A":"通胀对失业的敏感度","B":"失业率每高于自然率1个百分点，GDP低于潜在产出的百分比","C":"货币流通速度","D":"边际消费倾向"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP01_5","num":"5","stem":"奥肯定律是：","options":{"A":"理论推导的精确关系","B":"经验规律，不同国家β不同","C":"长期关系","D":"只适用于美国"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP01_6","num":"6","stem":"当经济过热，失业率低于自然率时：","options":{"A":"GDP高于潜在产出","B":"GDP低于潜在产出","C":"GDP等于潜在产出","D":"与潜在产出无关"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP01_7","num":"7","stem":"奥肯定律β>1（美国为2）的原因是：","options":{"A":"失业不仅减少劳动投入，还有乘数效应和资本闲置","B":"工人效率下降","C":"技术退步","D":"政府支出减少"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP01_8","num":"8","stem":"2020年4月美国失业率达14.7%，按奥肯定律，GDP缺口约为：","options":{"A":"-4%","B":"-10%","C":"-20%","D":"-30%"},"answer":"C"},{"id":"west_econ_13_失业通胀与经济周期_KP01_9","num":"9","stem":"关于奥肯定律，下列说法错误的是：","options":{"A":"它是短期关系","B":"它描述失业与产出的反向关系","C":"长期中失业率回到自然率，GDP缺口为零","D":"它适用于所有国家同一β值"},"answer":"D"}]},{"id":"KP02","name":"通货膨胀成因","file":"教材笔记/06_西方经济学/13_失业通胀与经济周期/知识点/KP02_通货膨胀成因.md","questions":[{"id":"west_econ_13_失业通胀与经济周期_KP02_1","num":"1","stem":"需求拉上型通货膨胀的成因是：","options":{"A":"总需求过度膨胀，\"太多货币追逐太少商品\"","B":"石油等原材料涨价","C":"工资上涨过快","D":"经济结构部门差异"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP02_2","num":"2","stem":"成本推动型通胀在AD-AS模型中表现为：","options":{"A":"AD右移","B":"SRAS左移","C":"LRAS右移","D":"AD左移"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP02_3","num":"3","stem":"\"通货膨胀无论何时何地都是一种货币现象\"是谁的观点？","options":{"A":"凯恩斯","B":"弗里德曼","C":"萨缪尔森","D":"菲利普斯"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP02_4","num":"4","stem":"根据数量方程式 $MV=PY$，若货币供给增长10%，产出增长3%，流通速度不变，通胀率为：","options":{"A":"3%","B":"7%","C":"10%","D":"13%"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP02_5","num":"5","stem":"下列哪一项属于通货膨胀的\"菜单成本\"？","options":{"A":"人们频繁跑银行取钱","B":"企业频繁印刷新价格表","C":"债务人获利","D":"资本利得税扭曲"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP02_6","num":"6","stem":"皮鞋成本是指：","options":{"A":"鞋子涨价","B":"通胀使人们不愿持有现金，频繁跑银行浪费资源","C":"制鞋业成本上升","D":"通勤成本上升"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP02_7","num":"7","stem":"通货膨胀的财富再分配效应是：","options":{"A":"债务人获利，债权人受损","B":"债权人获利，债务人受损","C":"固定收入者获利","D":"政府受损"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP02_8","num":"8","stem":"2021—2022年美国通胀从1.5%冲到9%的原因是：","options":{"A":"单纯需求拉上","B":"单纯成本推动","C":"需求拉上与成本推动双重作用","D":"紧缩货币政策"},"answer":"C"},{"id":"west_econ_13_失业通胀与经济周期_KP02_9","num":"9","stem":"关于通货紧缩，下列说法正确的是：","options":{"A":"物价持续下降对经济有利","B":"通缩使居民推迟消费，企业推迟投资，经济陷入衰退","C":"通缩与通胀无关","D":"日本\"失去的二十年\"是通缩的反面案例"},"answer":"B"}]},{"id":"KP03","name":"菲利普斯曲线","file":"教材笔记/06_西方经济学/13_失业通胀与经济周期/知识点/KP03_菲利普斯曲线.md","questions":[{"id":"west_econ_13_失业通胀与经济周期_KP03_1","num":"1","stem":"原始菲利普斯曲线描述的关系是：","options":{"A":"工资增长率与失业率反向关系","B":"通胀率与利率反向关系","C":"汇率与出口反向关系","D":"税率与税收收入反向关系"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP03_2","num":"2","stem":"附加预期的菲利普斯曲线方程是：","options":{"A":"$\\pi = \\pi^e - \\beta(u-u_n)$","B":"$\\pi = \\pi^e + \\beta(u-u_n)$","C":"$Y = Y_f + \\alpha(P-P^e)$","D":"$(Y-Y_f)/Y_f = -\\beta(u-u_n)$"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP03_3","num":"3","stem":"已知 $\\pi^e=2\\%$，$\\beta=0.5$，$u_n=5\\%$，当 $u=3\\%$ 时，通胀率为：","options":{"A":"1%","B":"2%","C":"3%","D":"4%"},"answer":"C"},{"id":"west_econ_13_失业通胀与经济周期_KP03_4","num":"4","stem":"长期菲利普斯曲线的形状是：","options":{"A":"向右下方倾斜","B":"垂直于自然失业率 $u_n$","C":"水平","D":"向右上方倾斜"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP03_5","num":"5","stem":"短期菲利普斯曲线向右下方倾斜意味着：","options":{"A":"通胀与失业存在短期替代关系","B":"通胀与失业长期替代","C":"通胀与失业无关","D":"降低通胀必然降低失业"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP03_6","num":"6","stem":"1970年代滞胀使菲利普斯曲线：","options":{"A":"向左下方移动","B":"向右上方移动","C":"变为垂直","D":"变为水平"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP03_7","num":"7","stem":"牺牲率是指：","options":{"A":"降低通胀1个百分点需要牺牲的GDP百分比","B":"提高通胀1个百分点带来的GDP增长","C":"失业率每上升1%的产出损失","D":"货币政策的操作成本"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP03_8","num":"8","stem":"自然失业率（NAIRU）是指：","options":{"A":"通胀加速时的失业率","B":"非加速通胀的失业率，即长期均衡失业率","C":"零失业","D":"周期性失业率"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP03_9","num":"9","stem":"政府持续把失业率压在自然率以下，长期结果是：","options":{"A":"失业率永久降低","B":"通胀率持续上升，失业率回到自然率","C":"通胀率下降","D":"产出永久高于潜在"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP03_10","num":"10","stem":"关于菲利普斯曲线，下列说法错误的是：","options":{"A":"短期向右下倾斜，长期垂直","B":"短期有替代关系，长期无替代关系","C":"供给冲击使曲线上移","D":"它在所有时期、所有国家都稳定成立"},"answer":"D"}]},{"id":"KP04","name":"适应性预期与理性预期","file":"教材笔记/06_西方经济学/13_失业通胀与经济周期/知识点/KP04_适应性预期与理性预期.md","questions":[{"id":"west_econ_13_失业通胀与经济周期_KP04_1","num":"1","stem":"适应性预期是指：","options":{"A":"人们根据所有信息预测未来","B":"人们根据过去经验慢慢调整预期","C":"人们随机猜测","D":"人们不做预期"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP04_2","num":"2","stem":"理性预期是指：","options":{"A":"人们完全预知未来","B":"人们利用所有可获得信息（包括政策信息）预测，不犯系统性错误","C":"人们根据上期通胀预测","D":"人们凭直觉预测"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP04_3","num":"3","stem":"在适应性预期下，扩张性政策：","options":{"A":"立刻无效","B":"短期有效，长期预期调整后失效","C":"长期有效","D":"完全无效"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP04_4","num":"4","stem":"在理性预期下，公开宣布的扩张性政策：","options":{"A":"短期有效","B":"立刻无效，因为工人同步要求涨工资","C":"长期有效","D":"只影响产出不影响物价"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP04_5","num":"5","stem":"卢卡斯批评是指：","options":{"A":"凯恩斯模型参数是政策不变时的经验关系，政策变了参数也变","B":"凯恩斯模型完全错误","C":"数学模型无用","D":"应该用更复杂的模型"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP04_6","num":"6","stem":"理性预期学派的政策主张是：","options":{"A":"积极相机抉择微调经济","B":"政府应保持政策一致性，建立央行信誉","C":"政府应该秘密操纵政策","D":"财政政策比货币政策有效"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP04_7","num":"7","stem":"下列哪种情况属于理性预期？","options":{"A":"学生看到央行宣布加息，立刻预期通胀下降","B":"学生去年通胀5%，今年就猜5%","C":"学生凭感觉猜通胀","D":"学生不关心通胀"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP04_8","num":"8","stem":"央行独立性的理论依据来自：","options":{"A":"凯恩斯主义","B":"理性预期学派——信誉稳定预期，降低反通胀成本","C":"货币主义单一规则","D":"供给学派"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP04_9","num":"9","stem":"关于理性预期，下列说法错误的是：","options":{"A":"人们不会犯系统性错误","B":"被预期到的政策无效","C":"理性预期等于完全预知未来","D":"卢卡斯批评反对用历史乘数预测政策"},"answer":"C"}]},{"id":"KP05","name":"经济周期与乘数-加速数","file":"教材笔记/06_西方经济学/13_失业通胀与经济周期/知识点/KP05_经济周期与乘数加速数.md","questions":[{"id":"west_econ_13_失业通胀与经济周期_KP05_1","num":"1","stem":"经济周期的四个阶段依次是：","options":{"A":"复苏—繁荣—衰退—萧条","B":"繁荣—复苏—衰退—萧条","C":"萧条—复苏—衰退—繁荣","D":"衰退—萧条—复苏—繁荣"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP05_2","num":"2","stem":"加速原理的表达式是：","options":{"A":"$I = vY$","B":"$I = v\\Delta Y$","C":"$I = vY^2$","D":"$I = v/Y$"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP05_3","num":"3","stem":"加速数 $v$ 的含义是：","options":{"A":"投资乘数","B":"资本-产出比，每增加1单位产出需要增加的资本","C":"边际消费倾向","D":"货币流通速度"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP05_4","num":"4","stem":"乘数-加速数模型说明：","options":{"A":"经济周期是外部冲击导致的","B":"经济周期是乘数与加速数相互作用内生产生的","C":"经济没有周期","D":"经济周期由政府政策导致"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP05_5","num":"5","stem":"当产出增速放缓时，加速原理使：","options":{"A":"投资增加","B":"投资下降，即使产出水平仍在增长","C":"投资不变","D":"产出水平下降"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP05_6","num":"6","stem":"熊彼特的经济周期理论是：","options":{"A":"消费不足论","B":"创新周期论——重大创新带来繁荣，扩散完后衰退","C":"货币信用论","D":"实际经济周期理论"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP05_7","num":"7","stem":"实际经济周期理论（RBC）认为经济波动的原因是：","options":{"A":"市场失灵","B":"技术冲击（供给侧）","C":"政府政策失误","D":"消费不足"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP05_8","num":"8","stem":"政府反周期政策的理论依据是：","options":{"A":"经济周期完全不可避免","B":"衰退时扩需求、过热时压需求可以平抑波动","C":"政府应该在繁荣时大力刺激","D":"政策不能影响周期"},"answer":"B"},{"id":"west_econ_13_失业通胀与经济周期_KP05_9","num":"9","stem":"关于乘数-加速数模型，下列说法错误的是：","options":{"A":"乘数使投资变动放大为产出变动","B":"加速数使产出变动引致投资变动","C":"两者相互作用产生内生周期","D":"它说明政府政策无法影响经济周期"},"answer":"D"}]},{"id":"KP99","name":"曲线移动专项","file":"","questions":[{"id":"west_econ_13_失业通胀与经济周期_KP99_1","num":"1","stem":"（曲线移动·判断题）社会预期通胀率 πe 上升，菲利普斯曲线如何移动？（　）","options":{"A":"整条菲利普斯曲线上移","B":"沿菲利普斯曲线向左上移动","C":"整条菲利普斯曲线下移","D":"曲线不动"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP99_2","num":"2","stem":"（曲线移动·判断题）石油价格暴涨（不利供给冲击），菲利普斯曲线如何移动？（　）","options":{"A":"上移（更高通胀与更高失业并存）","B":"下移","C":"不动","D":"变平缓"},"answer":"A"},{"id":"west_econ_13_失业通胀与经济周期_KP99_3","num":"3","stem":"（曲线移动·分析）长期中人们充分调整预期 πe=π，菲利普斯曲线变成什么形状？（　）","options":{"A":"垂直于自然失业率 un 的直线（通胀与失业无替代）","B":"向右下方倾斜","C":"水平","D":"向右上方倾斜"},"answer":"A"}]}]};
